import { test, expect } from '@playwright/test';
import { createHash } from 'node:crypto';
import { recognitionFixture } from '../fixtures/recognition.mjs';

// Mocked completed-job JSON and generated bytes only. This config serves Vite;
// these cases never start a model, capture a camera, or contact an installed DVR.
const id = 'a'.repeat(32), bytes = Buffer.from('generated completed-job source');
const sha = createHash('sha256').update(bytes).digest('hex');
const completed = {id, state:'completed', phase:'completed', recording:'generated.webm',
  frames_read:6, frames_analyzed:2, max_frames:6000, elapsed_seconds:1};
const panel = page => page.getByRole('region', {name:'Local recording analysis'});

async function setup(page, stallAt, retainReview = true) {
  const state = {stalled:[], writes:[], sessions:0};
  await page.route('**/api/**', route => {
    const request = route.request(), path = new URL(request.url()).pathname;
    if (request.method() === 'POST') state.writes.push(path);
    if (path === '/api/analysis/session') {
      state.sessions++;
      return route.fulfill({json:{token:'generated-opening-token', ready:true, recordings:[],
        models:[{id:'model', name:'Generated model'}], rules:[{id:'rules', name:'Generated rules', models:['model'], summary:[]}],
        recorder_active:false, job:completed}});
    }
    if (path === `/api/analysis/jobs/${id}/${stallAt}`) {state.stalled.push(route);return;}
    if (path === `/api/analysis/jobs/${id}/result`) return route.fulfill({json:recognitionFixture(sha)});
    if (path === `/api/analysis/jobs/${id}/source`) return route.fulfill({contentType:'video/webm', body:bytes});
    return route.fulfill({status:503, json:{error:{message:'No operation exists in this generated fixture.'}}});
  });
  await page.goto('/#recognition');
  if (retainReview) {
    await page.getByRole('button', {name:/^Open saved results/}).click();
    const previous = recognitionFixture('f'.repeat(64));
    previous.receipt.camera = previous.trace.camera = 'retained-generated-review';
    previous.receipt.events.forEach(event => {event.camera = 'retained-generated-review';});
    await page.getByLabel('Open recognition results').setInputFiles({name:'previous.json', mimeType:'application/json', buffer:Buffer.from(JSON.stringify(previous))});
    await expect(page.locator('.recognition-facts')).toContainText('retained-generated-review');
    await page.getByRole('button', {name:/^Analyze a recording/}).click();
  }
  await panel(page).getByRole('button', {name:'Connect local analysis', exact:true}).click();
  if (retainReview) await panel(page).getByRole('button', {name:'Open results', exact:true}).click();
  await expect.poll(() => state.stalled.length).toBe(1);
  return state;
}

for (const stallAt of ['result', 'source']) test(`completed-job ${stallAt} opening can cancel without replacing a review or releasing a newer opening`, async ({page}) => {
  const state = await setup(page, stallAt);
  const cancel = panel(page).getByRole('button', {name:'Cancel result opening', exact:true});
  const refresh = panel(page).getByRole('button', {name:'Refresh choices', exact:true});
  await expect(cancel).toBeEnabled();
  await expect(refresh).toBeDisabled();
  await cancel.click();
  await expect(refresh).toBeEnabled();
  await expect(panel(page).locator('.local-analysis-message')).toContainText('Opening cancelled');
  await expect(page.locator('.recognition-facts')).toContainText('retained-generated-review');

  await panel(page).getByRole('button', {name:'Open results again', exact:true}).click();
  await expect.poll(() => state.stalled.length).toBe(2);
  await state.stalled[0].fulfill(stallAt === 'result' ? {json:recognitionFixture(sha)} : {contentType:'video/webm', body:bytes}).catch(() => {});
  await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
  await expect(cancel).toBeEnabled();
  await expect(refresh).toBeDisabled();
  await cancel.click();
  await state.stalled[1].fulfill(stallAt === 'result' ? {json:recognitionFixture(sha)} : {contentType:'video/webm', body:bytes}).catch(() => {});
  await expect(refresh).toBeEnabled();
  await refresh.click();
  await expect.poll(() => state.sessions).toBe(2);
  await expect(refresh).toBeEnabled();
  await expect(cancel).toHaveCount(0);
  await expect(page.locator('.recognition-facts')).toContainText('retained-generated-review');
  expect(state.writes).toEqual([]);
  expect(await page.evaluate(() => JSON.parse(localStorage.getItem('dvr.events.v1') || '[]'))).toEqual([]);
});

test('a stalled automatic result opening reaches its deadline and leaves Refresh usable', async ({page}) => {
  await page.addInitScript(() => {
    const timeout = AbortSignal.timeout.bind(AbortSignal);
    Object.defineProperty(AbortSignal, 'timeout', {configurable:true,
      value:milliseconds => timeout(milliseconds === 120000 ? 250 : milliseconds)});
  });
  const state = await setup(page, 'source', false);
  const refresh = panel(page).getByRole('button', {name:'Refresh choices', exact:true});
  await expect(panel(page).locator('.local-analysis-message')).toContainText('Opening timed out');
  await expect(refresh).toBeEnabled();
  await expect(panel(page).getByRole('button', {name:'Open results again', exact:true})).toBeEnabled();
  await state.stalled[0].fulfill({contentType:'video/webm', body:bytes}).catch(() => {});
  await refresh.click();
  await expect.poll(() => state.sessions).toBe(2);
  await expect(refresh).toBeEnabled();
  await expect(page.locator('.recognition-facts')).toHaveCount(0);
  expect(state.writes).toEqual([]);
});
